class Order{int orderId;String orderDate;Order(int i,String d){orderId=i;orderDate=d;}String getOrderStatus(){return "Ordered";}}
class ShippedOrder extends Order{String trackingNumber;ShippedOrder(int i,String d,String t){super(i,d);trackingNumber=t;}String getOrderStatus(){return "Shipped";}}
class DeliveredOrder extends ShippedOrder{String deliveryDate;DeliveredOrder(int i,String d,String t,String dd){super(i,d,t);deliveryDate=dd;}String getOrderStatus(){return "Delivered";}}